[
  {
    "pd_decision_conflict": "It tears me up a little to choose this way",
    "sys_consequence_reasoning": "Five years against three isn't a fair trade",
    "sys_instrumental_norm_use": "holding to that instinct as long as it actually saves me time"
  },
  {
    "pd_decision_conflict": "this pulls me in two directions and I hate sitting with that",
    "sys_consequence_reasoning": "picking silence means a longer sentence with nothing gained",
    "pda_self_consequence_regret": "I'll regret not finding another way"
  },
  {
    "pd_decision_conflict": "I keep running the numbers and neither one sits right",
    "sys_consequence_reasoning": "costs me two extra years for nothing",
    "sys_instrumental_norm_use": "kept my word this far because it seemed like it'd protect me too"
  },
  {
    "pd_decision_conflict": "There's a knot in my stomach thinking this through",
    "sys_consequence_reasoning": "loyalty with no return isn't a deal I can keep making",
    "sys_instrumental_norm_use": "went along with staying silent expecting it'd pay off eventually"
  },
  {
    "pd_decision_conflict": "I don't like this option, none of them feel good",
    "sys_instrumental_norm_use": "Keeping quiet was worth it to me only while there was a chance",
    "sys_consequence_reasoning": "silence just means I lose more for nothing",
    "pda_self_consequence_regret": "carry the disappointment about how this played out"
  },
  {
    "pd_decision_conflict": "This decision's been chewing at me for a while now",
    "sys_instrumental_norm_use": "only ever sticking to that because it kept my risk down",
    "sys_consequence_reasoning": "Three years I can build a plan around; five feels like a waste",
    "pda_self_consequence_regret": "kicking myself over for a long time"
  },
  {
    "pd_decision_conflict": "It's an ugly choice and I won't pretend otherwise",
    "sys_instrumental_norm_use": "agreed to stay quiet because it looked like the smart move for both",
    "sys_consequence_reasoning": "once that logic breaks I'm not obligated to it anymore"
  },
  {
    "pd_decision_conflict": "there was never a version of this where I come out unscathed",
    "sys_instrumental_norm_use": "stuck with the plan to stay silent only because I thought it protected me",
    "pda_self_consequence_regret": "accepting I'll carry some regret over the years I'm still losing"
  },
  {
    "pd_decision_conflict": "I feel pulled apart deciding this",
    "sys_instrumental_norm_use": "My silence was always conditional on it working out for me too",
    "sys_consequence_reasoning": "Now it's just five years wasted",
    "pda_self_consequence_regret": "mourn the missed opportunity to end this differently"
  },
  {
    "pd_decision_conflict": "There's real tension in weighing this",
    "sys_instrumental_norm_use": "made that promise expecting mutual protection, and that's off the table now",
    "sys_consequence_reasoning": "Silence just costs me more with nothing to show for it",
    "pda_self_consequence_regret": "accepting the sting of losing the outcome I hoped for"
  }
]
